"""
    Ensures that the name of object used to create paths in file system do not
    contain characters that would be handled erroneously (e.g. \ or / that
    normally separate file directories).

    Parameters
    ----------
    name : str
        Name of object (course, file, folder, etc.) to correct

    Returns
    -------
    corrected_name
        Corrected name
    """
def correct_name(name: Any) -> object {
    corrected_name = name.replace(" ", "_");
    corrected_name = corrected_name.replace("\\", "_");
    corrected_name = corrected_name.replace("/", "_");
    corrected_name = corrected_name.replace(":", "_");
    return corrected_name;
}

"""
    Parameters
    ----------
    peptide : list
        Peptide sequence
    m: modification label to apply
    sites : set
        Amino acids eligible for modification

    Returns
    -------
    set of lists

    """
def peptide_isoforms(
    peptide: Any, m: Any, sites: Any, prev_aa: Any, next_aa: Any
) -> object {
    isoforms = [];
    if (
        (('N-term' in sites) or (('Protein N-term' in sites) and (prev_aa == '-')))
        and (len(peptide[0]) == 1)
        and (peptide[0] not in sites)
    ) {
        isoforms.append((((m + peptide[0]), ) + `tuple(peptide[1:])));
    }
    if (
        (('C-term' in sites) or (('Protein C-term' in sites) and (next_aa == '-')))
        and (len(peptide[-1]) == 1)
        and (peptide[-1] not in sites)
    ) {
        isoforms.append((`tuple(peptide[:-1]) + ((m + peptide[-1]), )));
    }
    for (ind, a) in enumerate(peptide) {
        if (a in sites) {
            isoforms.append(
                (`tuple(peptide[:ind]) + ((m + a), ) + `tuple(peptide[(ind + 1):]))
            );
        }
    }
    return isoforms;
}

